from reportlab.lib import colors
from reportlab.lib.enums import TA_CENTER
from reportlab.lib.pagesizes import A4
from reportlab.lib.styles import getSampleStyleSheet, ParagraphStyle
from reportlab.lib.units import mm
from reportlab.platypus import SimpleDocTemplate, Paragraph, Spacer, PageBreak, Table, TableStyle, KeepTogether
from reportlab.pdfbase import pdfmetrics
from reportlab.pdfbase.ttfonts import TTFont

OUT = 'output/pdf/yachiyo-app-handbook.pdf'
pdfmetrics.registerFont(TTFont('SegoeSymbol', 'C:/Windows/Fonts/seguisym.ttf'))
doc = SimpleDocTemplate(OUT, pagesize=A4, rightMargin=18*mm, leftMargin=18*mm, topMargin=18*mm, bottomMargin=18*mm)
pink = colors.HexColor('#e9a6c2'); ink = colors.HexColor('#28232f'); muted = colors.HexColor('#655b69'); panel = colors.HexColor('#f8eef4')
styles = getSampleStyleSheet()
styles.add(ParagraphStyle(name='CoverTitle', parent=styles['Title'], alignment=TA_CENTER, fontName='SegoeSymbol', fontSize=30, leading=36, textColor=ink, spaceAfter=12))
styles.add(ParagraphStyle(name='CoverSub', parent=styles['Normal'], alignment=TA_CENTER, fontSize=13, leading=19, textColor=muted, spaceAfter=20))
styles.add(ParagraphStyle(name='H1x', parent=styles['Heading1'], fontSize=18, leading=23, textColor=ink, spaceBefore=12, spaceAfter=7))
styles.add(ParagraphStyle(name='H2x', parent=styles['Heading2'], fontSize=12, leading=16, textColor=colors.HexColor('#9b5875'), spaceBefore=9, spaceAfter=4))
styles.add(ParagraphStyle(name='Bodyx', parent=styles['BodyText'], fontSize=9.5, leading=14, textColor=ink, spaceAfter=6))
styles.add(ParagraphStyle(name='Smallx', parent=styles['BodyText'], fontSize=8, leading=11, textColor=muted))
styles.add(ParagraphStyle(name='Command', parent=styles['BodyText'], fontName='Courier', fontSize=8.3, leading=12, textColor=ink, leftIndent=8, rightIndent=8, spaceAfter=2))

def footer(canvas, doc):
    canvas.saveState(); canvas.setStrokeColor(pink); canvas.line(18*mm, 13*mm, 192*mm, 13*mm)
    canvas.setFont('Helvetica', 8); canvas.setFillColor(muted); canvas.drawString(18*mm, 8*mm, 'Yachiyo • Discord server companion • Created by. Sereia')
    canvas.drawRightString(192*mm, 8*mm, f'Page {doc.page}'); canvas.restoreState()

def section(title, intro, rows):
    items=[Paragraph(title, styles['H1x']), Paragraph(intro, styles['Bodyx'])]
    data=[[Paragraph('<b>Command</b>', styles['Bodyx']), Paragraph('<b>Use</b>', styles['Bodyx']), Paragraph('<b>Access</b>', styles['Bodyx'])]]
    for cmd, use, access in rows: data.append([Paragraph(cmd, styles['Command']), Paragraph(use, styles['Bodyx']), Paragraph(access, styles['Bodyx'])])
    t=Table(data, colWidths=[43*mm, 91*mm, 35*mm], repeatRows=1)
    t.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,0),pink),('TEXTCOLOR',(0,0),(-1,0),ink),('BACKGROUND',(0,1),(-1,-1),panel),('GRID',(0,0),(-1,-1),0.25,colors.HexColor('#ead6df')),('VALIGN',(0,0),(-1,-1),'TOP'),('LEFTPADDING',(0,0),(-1,-1),6),('RIGHTPADDING',(0,0),(-1,-1),6),('TOPPADDING',(0,0),(-1,-1),5),('BOTTOMPADDING',(0,0),(-1,-1),5)]))
    items.append(t); return items

story=[Spacer(1,30*mm), Paragraph('☾ YACHIYO', styles['CoverTitle']), Paragraph('Official App Handbook', styles['CoverTitle']), Paragraph('A formal guide to Yachiyo’s features, commands, permissions, and everyday use.', styles['CoverSub']), Spacer(1,12*mm), Table([[Paragraph('<b>Public Discord companion</b><br/>Moderation • Server management • Community tools', styles['Bodyx'])]], colWidths=[120*mm], style=TableStyle([('BACKGROUND',(0,0),(-1,-1),panel),('BOX',(0,0),(-1,-1),1,pink),('LEFTPADDING',(0,0),(-1,-1),15),('RIGHTPADDING',(0,0),(-1,-1),15),('TOPPADDING',(0,0),(-1,-1),15),('BOTTOMPADDING',(0,0),(-1,-1),15)])), Spacer(1,18*mm), Paragraph('Created by. Sereia<br/>Version 1.0 • August 2026', styles['CoverSub']), PageBreak()]
story += [Paragraph('1. Overview', styles['H1x']), Paragraph('Yachiyo is a public Discord application designed to help server owners and staff create organized, welcoming, and well-moderated communities. Its settings are stored persistently so configured features remain available after a restart.', styles['Bodyx']), Paragraph('Yachiyo is focused on server management, moderation, community panels, profiles, tickets, reminders, and interactive tools. Economy and fishing features are provided by Kaguya-App.', styles['Bodyx']), Paragraph('2. Installation and permissions', styles['H1x']), Paragraph('To add Yachiyo, open her Discord profile, choose <b>Add App</b>, select <b>Add to Server</b>, choose a server where you have Manage Server permission, and authorize the requested permissions. Yachiyo must be installed with the <b>bot</b> and <b>applications.commands</b> scopes.', styles['Bodyx']), Paragraph('Recommended permissions include View Channels, Send Messages, Embed Links, Attach Files, Read Message History, Manage Messages, Manage Roles, Manage Channels, Add Reactions, Moderate Members, Connect, and Speak. Grant only the permissions needed by your server.', styles['Bodyx']), Paragraph('3. General use', styles['H1x']), Paragraph('Most features are slash commands. Type <b>/</b> in a channel and select the command from Discord’s command menu. Commands marked Admin require Administrator permission; staff commands use the relevant Discord permission. Setup commands normally save the configuration and publish or refresh a panel in the selected channel.', styles['Bodyx']), Paragraph('4. Public support', styles['H1x']), Paragraph('Use the following command to open Yachiyo’s official bug-report form:', styles['Bodyx']), Paragraph('<b>/report-bug</b> — Opens a panel with a REPORT HERE button. Anyone may use it to report a bug, error, or unexpected behavior.', styles['Bodyx']), Paragraph('Please include the command used, the expected result, the actual result, the server and channel context when relevant, and screenshots that do not expose passwords or private tokens.', styles['Bodyx']), PageBreak()]

